/* Stageshow Gallery service worker. Generated by scripts/build-sw.mjs; do not edit public/sw.js. */
const VERSION = "__VERSION__";
const PRECACHE = `precache-${VERSION}`;
const RUNTIME = `runtime-${VERSION}`;
const PAGES = __PAGES__;
const ASSETS = __ASSETS__;
const OFFLINE_URL = "/offline";

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(PRECACHE);
      // `cache: "reload"` skips the HTTP cache so a deploy never precaches stale HTML.
      await cache.addAll([...PAGES, ...ASSETS].map((url) => new Request(url, { cache: "reload" })));
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.filter((k) => k !== PRECACHE && k !== RUNTIME).map((k) => caches.delete(k)));
      if (self.registration.navigationPreload) await self.registration.navigationPreload.enable();
      await self.clients.claim();
      const clients = await self.clients.matchAll({ type: "window" });
      clients.forEach((c) => c.postMessage({ type: "PRECACHED", version: VERSION }));
    })(),
  );
});

async function fromCache(request, options) {
  return (await caches.match(request, options)) || undefined;
}

// Pages: network first so online visitors always get the latest deploy,
// then the precached copy, then the offline page.
async function handleNavigation(event) {
  const { request } = event;
  try {
    const preload = await event.preloadResponse;
    const response = preload || (await fetch(request));
    if (response.ok) {
      const copy = response.clone();
      const url = new URL(request.url);
      caches.open(RUNTIME).then((c) => c.put(url.pathname, copy));
    }
    return response;
  } catch {
    const url = new URL(request.url);
    return (
      (await fromCache(url.pathname, { ignoreSearch: true })) ||
      (await fromCache(OFFLINE_URL)) ||
      new Response("Offline", { status: 503, headers: { "Content-Type": "text/plain" } })
    );
  }
}

// React Server Component payloads for client-side navigation. Offline, an
// unknown payload errors so the router falls back to a full page load, which
// the navigation handler serves from the precache.
async function handleRsc(request) {
  try {
    const response = await fetch(request);
    if (response.ok) {
      const copy = response.clone();
      caches.open(RUNTIME).then((c) => c.put(request, copy));
    }
    return response;
  } catch {
    return (await fromCache(request)) || Response.error();
  }
}

// Hashed build assets and icons never change for a given URL: cache first.
async function handleAsset(request) {
  const cached = await fromCache(request, { ignoreVary: true });
  if (cached) return cached;
  const response = await fetch(request);
  if (response.ok) {
    const copy = response.clone();
    caches.open(RUNTIME).then((c) => c.put(request, copy));
  }
  return response;
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (request.mode === "navigate") {
    event.respondWith(handleNavigation(event));
  } else if (request.headers.get("RSC") === "1") {
    event.respondWith(handleRsc(request));
  } else if (url.pathname.startsWith("/_next/static/") || url.pathname.startsWith("/icons/") || ASSETS.includes(url.pathname)) {
    event.respondWith(handleAsset(request));
  }
});
